import React, { useEffect, useState, useRef, useMemo } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { getImageUrl } from '../services/api';
import { motion, AnimatePresence } from 'framer-motion';
import styles from './AdminPanel.module.css';

/* ================= ПОЛНЫЙ СПИСОК МАРОК И МОДЕЛЕЙ ================= */
const brandModels = {
  "BMW": ["1 Series", "2 Series Gran Coupe", "2 Series Coupe", "3 Series Sedan", "3 Series Touring",
    "4 Series Gran Coupe", "4 Series Coupe", "5 Series Sedan", "5 Series Touring",
    "6 Series Gran Coupe", "7 Series", "8 Series Gran Coupe", "8 Series Coupe",
    "X1", "X2", "X3", "X4", "X5", "X6", "X7", "XM",
    "M2 Coupe", "M3 Sedan", "M3 Touring", "M4 Coupe", "M5 Sedan", "M8 Gran Coupe",
    "Z4 Roadster", "i4 Gran Coupe", "i5 Sedan", "i7 Sedan", "iX SUV"
  ],
  "Mercedes-Benz": ["A-Class Hatchback", "A-Class Sedan", "B-Class", "C-Class Sedan", "C-Class Estate",
    "E-Class Sedan", "E-Class Estate", "S-Class Sedan", "S-Class Maybach",
    "CLA Coupe", "CLA Shooting Brake", "CLS Coupe", "GLA SUV", "GLB SUV",
    "GLC SUV", "GLC Coupe", "GLE SUV", "GLE Coupe", "GLS SUV",
    "G-Class SUV", "EQS Sedan", "EQS SUV", "EQE Sedan", "EQE SUV",
    "SL Roadster", "AMG GT Coupe", "AMG GT 4-Door Coupe"
  ],
  "Audi": ["A1 Sportback", "A3 Sportback", "A3 Sedan", "A4 Sedan", "A4 Avant",
    "A5 Sportback", "A5 Coupe", "A6 Sedan", "A6 Avant", "A7 Sportback",
    "A8 Sedan", "Q2", "Q3", "Q3 Sportback", "Q5", "Q5 Sportback",
    "Q7", "Q8", "e-tron", "e-tron Sportback", "e-tron GT", "R8 Coupe", "TT Coupe"
  ],
  "Porsche": ["718 Cayman", "718 Boxster", "911 Carrera", "911 Carrera S", "911 Turbo",
    "911 Turbo S", "911 GT3", "911 GT3 RS", "Taycan", "Taycan Cross Turismo",
    "Panamera", "Panamera Sport Turismo", "Cayenne", "Cayenne Coupe", "Macan", "Macan GTS", "Macan S", "Macan Turbo"
  ],
  "Lexus": ["IS 300", "ES 250", "ES 350", "LS 500", "LC 500", "RC F", "UX 200", "NX 350", "RX 350", "RX 500h", "GX 460", "LX 600"],
  "Bentley": ["Bentayga", "Bentayga EWB", "Continental GT", "Continental GTC", "Flying Spur"],
  "Rolls-Royce": ["Ghost", "Ghost Extended", "Phantom", "Phantom Extended", "Cullinan", "Wraith", "Dawn"],
  "Lamborghini": ["Huracán EVO", "Huracán STO", "Aventador SVJ", "Urus", "Revuelto"],
  "Ferrari": ["Roma", "Portofino M", "SF90 Stradale", "296 GTB", "812 Superfast", "F8 Tributo"],
  "McLaren": ["GT", "720S", "765LT", "Artura"],
  "Land Rover": ["Range Rover", "Range Rover Sport", "Range Rover Velar", "Range Rover Evoque", "Discovery", "Discovery Sport", "Defender 90", "Defender 110"],
  "Jaguar": ["XE", "XF", "F-Type Coupe", "F-Type Convertible", "E-Pace", "F-Pace", "I-Pace"],
  "Maserati": ["Ghibli", "Quattroporte", "Levante", "MC20", "Grecale"],
  "Aston Martin": ["Vantage", "Vantage Roadster", "DB11", "DBX", "DBS Superleggera"],
  "Cadillac": ["CT4", "CT5", "Escalade", "XT5", "XT6"],
  "Infiniti": ["Q50", "Q60", "QX50", "QX55", "QX60", "QX80"],
  "Genesis": ["G70", "G80", "G90", "GV70", "GV80"],
  "Bugatti": ["Chiron", "Chiron Super Sport", "Divo", "Centodieci", "Mistral"],
  "Koenigsegg": ["Jesko", "Gemera", "Regera", "CC850"],
  "Pagani": ["Huayra", "Huayra BC", "Utopia", "Zonda R"],
  "Alfa Romeo": ["Giulia", "Giulia Quadrifoglio", "Stelvio", "Tonale"],
  "Lotus": ["Emira", "Evija", "Eletre"],
  "Rimac": ["Nevera"],
  "Polestar": ["Polestar 1", "Polestar 2", "Polestar 3", "Polestar 4"],
  "Lucid": ["Air", "Air Grand Touring", "Gravity"]
};

const bodyTypesRussian = {
  "sedan": "Седан", "coupe": "Купе", "cabriolet": "Кабриолет", "wagon": "Универсал",
  "suv": "Внедорожник", "pickup": "Пикап", "limousine": "Лимузин", "hatchback": "Хэтчбек",
};

const availableRoles = ["user", "admin", "manager"];

const getDefaultSpecs = (brand, model, bodyType, year) => {
  const specs = {
    engine_volume: 2.0, power: 200, fuel_type: "petrol", consumption: 8.0,
    drive_type: "RWD", transmission: "automatic", acceleration: 7.0,
    max_speed: 240, clearance: 140, seats: 5
  };
  if (bodyType) {
    if (bodyType === "suv" || bodyType === "pickup") {
      specs.engine_volume = 3.0; specs.power = 300; specs.consumption = 10.5;
      specs.drive_type = "AWD"; specs.clearance = 200; specs.seats = 5;
    } else if (bodyType === "coupe" || bodyType === "cabriolet") {
      specs.seats = 4; specs.acceleration = 5.0; specs.max_speed = 270; specs.clearance = 120;
    } else if (bodyType === "wagon") {
      specs.consumption = 7.5; specs.seats = 5;
    } else if (bodyType === "limousine") {
      specs.engine_volume = 4.0; specs.power = 400; specs.seats = 7; specs.clearance = 130;
    }
  }
  if (brand === "BMW" || brand === "Porsche") {
    specs.drive_type = "RWD"; specs.transmission = "automatic";
  } else if (brand === "Audi") {
    specs.drive_type = "AWD";
  } else if (brand === "Mercedes-Benz" && bodyType === "suv") {
    specs.drive_type = "AWD";
  } else if (["Lamborghini", "Ferrari", "McLaren"].includes(brand)) {
    specs.power = 600; specs.acceleration = 3.0; specs.max_speed = 330;
    specs.clearance = 110; specs.seats = 2; specs.engine_volume = 4.0; specs.fuel_type = "petrol";
  } else if (brand === "Rolls-Royce" || brand === "Bentley") {
    specs.power = 500; specs.engine_volume = 6.0; specs.clearance = 130; specs.seats = 5;
  } else if (brand === "Land Rover") {
    specs.drive_type = "AWD"; specs.clearance = 220; specs.power = 350; specs.engine_volume = 3.0;
  } else if (brand === "Bugatti") {
    specs.power = 1000; specs.engine_volume = 8.0; specs.acceleration = 2.5;
    specs.max_speed = 420; specs.clearance = 100; specs.seats = 2;
  }
  if (year) {
    const y = parseInt(year);
    if (!isNaN(y) && y >= 2020) {
      specs.power = Math.round(specs.power * 1.05);
      specs.consumption = Math.round((specs.consumption * 0.95) * 10) / 10;
      if (specs.transmission === "manual" && y >= 2022) specs.transmission = "automatic";
    }
  }
  return specs;
};

const engineVolumes = [1.6, 2.0, 2.5, 3.0, 4.0, 4.4, 5.0, 6.0, 8.0];
const powerValues = [150, 200, 249, 300, 400, 500, 600, 700, 1000];
const seatValues = [2, 4, 5, 7];

const AdminPanel = () => {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [stats, setStats] = useState(null);
  const [users, setUsers] = useState([]);
  const [cars, setCars] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loans, setLoans] = useState([]);
  const [loading, setLoading] = useState(true);

  // Состояния для фильтрации автомобилей
  const [carSearch, setCarSearch] = useState('');
  const [brandFilter, setBrandFilter] = useState('');
  const [bodyTypeFilter, setBodyTypeFilter] = useState('');
  const [priceMin, setPriceMin] = useState('');
  const [priceMax, setPriceMax] = useState('');
  const [sortField, setSortField] = useState('id');
  const [sortOrder, setSortOrder] = useState('asc');

  // Форма для автомобилей
  const [showCarModal, setShowCarModal] = useState(false);
  const [editingCarId, setEditingCarId] = useState(null);
  const [carForm, setCarForm] = useState({
    brand: '', model: '', year: new Date().getFullYear(), price: '',
    body_type: 'sedan', description: '', is_available: true,
    engine_volume: 2.0, power: 200, fuel_type: 'petrol', consumption: 8.0,
    drive_type: 'RWD', transmission: 'automatic', acceleration: 7.0,
    max_speed: 240, clearance: 140, seats: 5
  });

  // Умные выпадающие списки марок/моделей
  const [showBrandModal, setShowBrandModal] = useState(false);
  const [showModelModal, setShowModelModal] = useState(false);
  const [brandSearch, setBrandSearch] = useState('');
  const [modelSearch, setModelSearch] = useState('');

  // Загрузка изображений
  const [selectedFiles, setSelectedFiles] = useState([]);
  const [uploadingImages, setUploadingImages] = useState(false);
  const fileInputRef = useRef(null);

  // Валидация
  const [formErrors, setFormErrors] = useState({});
  const [serverError, setServerError] = useState('');

  // Состояние комментария для отказа в кредите
  const [showCommentModal, setShowCommentModal] = useState(false);
  const [selectedLoanId, setSelectedLoanId] = useState(null);
  const [rejectComment, setRejectComment] = useState('');

  useEffect(() => {
    fetchAdminData();
  }, []);

  const fetchAdminData = async () => {
    try {
      setLoading(true);
      const [statsRes, usersRes, carsRes, tdRes, loansRes] = await Promise.all([
        api.get('/admin/stats').catch(() => ({ data: null })),
        api.get('/admin/users').catch(() => ({ data: [] })),
        api.get('/cars').catch(() => ({ data: [] })),
        api.get('/admin/test-drives').catch(() => ({ data: [] })),
        api.get('/admin/loans').catch(() => ({ data: [] }))
      ]);
      setStats(statsRes.data);
      setUsers(usersRes.data || []);
      setCars(carsRes.data || []);
      setTestDrives(tdRes.data || []);
      setLoans(loansRes.data || []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleRoleChange = async (userId, newRole) => {
    try {
      await api.put(`/admin/users/${userId}/role`, null, { params: { role: newRole } });
      setUsers(users.map(u => u.id === userId ? { ...u, role: newRole } : u));
    } catch (err) {
      alert('Ошибка при изменении роли');
    }
  };

  const handleTestDriveStatus = async (tdId, status) => {
    try {
      await api.put(`/admin/test-drives/${tdId}/status`, null, { params: { status } });
      setTestDrives(testDrives.map(td => td.id === tdId ? { ...td, status } : td));
    } catch (err) {
      alert('Ошибка изменения статуса тест-драйва');
    }
  };

  const handleLoanStatus = async (loanId, status, comment = '') => {
    try {
      await api.put(`/admin/loans/${loanId}/status`, null, { params: { status, comment } });
      setLoans(loans.map(l => l.id === loanId ? { ...l, status, comment } : l));
    } catch (err) {
      alert(err.response?.data?.detail || 'Ошибка изменения статуса кредита');
    }
  };

  const openRejectCommentModal = (loanId) => {
    setSelectedLoanId(loanId);
    setRejectComment('');
    setShowCommentModal(true);
  };

  const submitLoanReject = async () => {
    if (!rejectComment.trim()) {
      alert('Пожалуйста, укажите причину отказа');
      return;
    }
    await handleLoanStatus(selectedLoanId, 'rejected', rejectComment);
    setShowCommentModal(false);
  };

  // Валидация перед отправкой автомобиля
  const validateCarForm = () => {
    const errors = {};
    if (!carForm.brand) errors.brand = 'Выберите марку автомобиля';
    if (!carForm.model) errors.model = 'Выберите модель автомобиля';
    if (!carForm.year || carForm.year < 1900 || carForm.year > new Date().getFullYear() + 1) {
      errors.year = `Укажите корректный год (1900-${new Date().getFullYear() + 1})`;
    }
    if (!carForm.price || parseFloat(carForm.price) <= 0) {
      errors.price = 'Цена должна быть больше нуля';
    }
    if (carForm.engine_volume <= 0) errors.engine_volume = 'Объем должен быть больше 0';
    if (carForm.power <= 0) errors.power = 'Мощность должна быть больше 0';
    if (carForm.consumption < 0) errors.consumption = 'Расход не может быть отрицательным';
    if (carForm.acceleration < 0) errors.acceleration = 'Разгон не может быть отрицательным';
    if (carForm.max_speed <= 0) errors.max_speed = 'Скорость должна быть больше 0';
    if (carForm.clearance <= 0) errors.clearance = 'Клиренс должен быть больше 0';
    if (carForm.seats <= 0) errors.seats = 'Количество мест должно быть больше 0';

    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleCarFormSubmit = async (e) => {
    e.preventDefault();
    setServerError('');
    if (!validateCarForm()) return;

    try {
      const payload = {
        brand: carForm.brand,
        model: carForm.model,
        year: parseInt(carForm.year),
        price: parseFloat(carForm.price),
        body_type: carForm.body_type,
        description: carForm.description,
        is_available: carForm.is_available,
        specs: {
          engine_volume: parseFloat(carForm.engine_volume),
          power: parseInt(carForm.power),
          fuel_type: carForm.fuel_type,
          consumption: parseFloat(carForm.consumption),
          drive_type: carForm.drive_type,
          transmission: carForm.transmission,
          acceleration: parseFloat(carForm.acceleration),
          max_speed: parseInt(carForm.max_speed),
          clearance: parseInt(carForm.clearance),
          seats: parseInt(carForm.seats)
        }
      };

      let savedCar;
      if (editingCarId) {
        const res = await api.put(`/cars/${editingCarId}`, payload);
        savedCar = res.data;
        setCars(cars.map(c => c.id === editingCarId ? savedCar : c));
      } else {
        const res = await api.post('/cars', payload);
        savedCar = res.data;
        setCars([savedCar, ...cars]);
      }

      // Загрузка фото, если они выбраны
      if (selectedFiles.length > 0) {
        setUploadingImages(true);
        const formData = new FormData();
        selectedFiles.forEach(file => formData.append('files', file));
        const imgRes = await api.post(`/cars/${savedCar.id}/images`, formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
        setCars(prev => prev.map(c => c.id === savedCar.id ? { ...c, images: imgRes.data.images || imgRes.data } : c));
      }

      setShowCarModal(false);
      resetCarForm();
    } catch (err) {
      setServerError(err.response?.data?.detail || 'Ошибка сохранения автомобиля. Проверьте введенные данные.');
    } finally {
      setUploadingImages(false);
    }
  };

  const resetCarForm = () => {
    setCarForm({
      brand: '', model: '', year: new Date().getFullYear(), price: '',
      body_type: 'sedan', description: '', is_available: true,
      engine_volume: 2.0, power: 200, fuel_type: 'petrol', consumption: 8.0,
      drive_type: 'RWD', transmission: 'automatic', acceleration: 7.0,
      max_speed: 240, clearance: 140, seats: 5
    });
    setEditingCarId(null);
    setSelectedFiles([]);
    setFormErrors({});
    setServerError('');
  };

  const openAddCarModal = () => {
    resetCarForm();
    setShowCarModal(true);
  };

  const openEditCarModal = (car) => {
    setEditingCarId(car.id);
    const sp = car.specs || {};
    setCarForm({
      brand: car.brand, model: car.model, year: car.year, price: car.price,
      body_type: car.body_type || 'sedan', description: car.description || '',
      is_available: car.is_available !== false,
      engine_volume: sp.engine_volume ?? 2.0, power: sp.power ?? 200,
      fuel_type: sp.fuel_type || 'petrol', consumption: sp.consumption ?? 8.0,
      drive_type: sp.drive_type || 'RWD', transmission: sp.transmission || 'automatic',
      acceleration: sp.acceleration ?? 7.0, max_speed: sp.max_speed ?? 240,
      clearance: sp.clearance ?? 140, seats: sp.seats ?? 5
    });
    setSelectedFiles([]);
    setFormErrors({});
    setServerError('');
    setShowCarModal(true);
  };

  const handleDeleteCar = async (carId) => {
    if (!window.confirm('Удалить этот автомобиль?')) return;
    try {
      await api.delete(`/cars/${carId}`);
      setCars(cars.filter(c => c.id !== carId));
    } catch (err) {
      alert('Ошибка при удалении автомобиля');
    }
  };

  const handleFileChange = (e) => {
    if (e.target.files) {
      setSelectedFiles(Array.from(e.target.files));
    }
  };

  const handleDeleteExistingImage = async (carId, imagePath) => {
    if (!window.confirm('Удалить это изображение?')) return;
    try {
      await api.delete(`/cars/${carId}/images`, { data: { image_path: imagePath } });
      setCars(cars.map(c => {
        if (c.id === carId) {
          return { ...c, images: c.images.filter(img => (img.image_path || img) !== imagePath) };
        }
        return c;
      }));
      if (editingCarId === carId) {
        setCarForm(prev => prev);
      }
    } catch (err) {
      alert('Ошибка удаления изображения');
    }
  };

  // Динамическая адаптация спецификаций при смене кузова/марки
  const handleBodyTypeChangeInForm = (newBodyType) => {
    const autoSpecs = getDefaultSpecs(carForm.brand, carForm.model, newBodyType, carForm.year);
    setCarForm(prev => ({ ...prev, body_type: newBodyType, ...autoSpecs }));
  };

  const selectBrand = (brand) => {
    setCarForm(prev => {
      const autoSpecs = getDefaultSpecs(brand, '', prev.body_type, prev.year);
      return { ...prev, brand, model: '', ...autoSpecs };
    });
    setShowBrandModal(false);
    setBrandSearch('');
  };

  const selectModel = (model) => {
    setCarForm(prev => {
      const autoSpecs = getDefaultSpecs(prev.brand, model, prev.body_type, prev.year);
      return { ...prev, model, ...autoSpecs };
    });
    setShowModelModal(false);
    setModelSearch('');
  };

  // Сортировка таблицы авто
  const handleSort = (field) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
  };

  // Сброс фильтров автомобилей
  const resetFilters = () => {
    setCarSearch(''); setBrandFilter(''); setBodyTypeFilter('');
    setPriceMin(''); setPriceMax('');
  };

  // Вычисляемые списки для поиска в модалках
  const filteredBrandKeys = useMemo(() => {
    return Object.keys(brandModels).filter(b => b.toLowerCase().includes(brandSearch.toLowerCase()));
  }, [brandSearch]);

  const filteredModels = useMemo(() => {
    if (!carForm.brand || !brandModels[carForm.brand]) return [];
    return brandModels[carForm.brand].filter(m => m.toLowerCase().includes(modelSearch.toLowerCase()));
  }, [carForm.brand, modelSearch]);

  // Фильтрация и сортировка основного массива машин
  const processedCars = useMemo(() => {
    let result = [...cars];
    if (carSearch) {
      const s = carSearch.toLowerCase();
      result = result.filter(c => c.brand.toLowerCase().includes(s) || c.model.toLowerCase().includes(s));
    }
    if (brandFilter) {
      result = result.filter(c => c.brand === brandFilter);
    }
    if (bodyTypeFilter) {
      result = result.filter(c => c.body_type === bodyTypeFilter);
    }
    if (priceMin) {
      result = result.filter(c => c.price >= parseFloat(priceMin));
    }
    if (priceMax) {
      result = result.filter(c => c.price <= parseFloat(priceMax));
    }

    result.sort((a, b) => {
      let valA = a[sortField];
      let valB = b[sortField];
      if (sortField === 'price' || sortField === 'year' || sortField === 'id') {
        valA = parseFloat(valA) || 0;
        valB = parseFloat(valB) || 0;
      } else {
        valA = String(valA).toLowerCase();
        valB = String(valB).toLowerCase();
      }
      if (valA < valB) return sortOrder === 'asc' ? -1 : 1;
      if (valA > valB) return sortOrder === 'asc' ? 1 : -1;
      return 0;
    });
    return result;
  }, [cars, carSearch, brandFilter, bodyTypeFilter, priceMin, priceMax, sortField, sortOrder]);

  // Преобразование статистики по брендам для круговой диаграммы
  const pieChartData = useMemo(() => {
    if (!stats || !stats.cars_by_brand) return [];
    const entries = Object.entries(stats.cars_by_brand);
    const total = entries.reduce((sum, [_, val]) => sum + val, 0);

    const colors = [
      '#4a148c', '#7b1fa2', '#9c27b0', '#ba68c8', '#e1bee7',
      '#311b92', '#512da8', '#673ab7', '#9575cd', '#d1c4e9'
    ];

    let accumulatedAngle = 0;

    return entries.map(([brand, count], idx) => {
      const percentage = total > 0 ? (count / total) * 100 : 0;
      const angle = total > 0 ? (count / total) * 360 : 0;

      // Вычисление координат для SVG Path круга
      const x1 = 80 + 70 * Math.cos((accumulatedAngle - 90) * Math.PI / 180);
      const y1 = 80 + 70 * Math.sin((accumulatedAngle - 90) * Math.PI / 180);
      accumulatedAngle += angle;
      const x2 = 80 + 70 * Math.cos((accumulatedAngle - 90) * Math.PI / 180);
      const y2 = 80 + 70 * Math.sin((accumulatedAngle - 90) * Math.PI / 180);

      const largeArcFlag = angle > 180 ? 1 : 0;
      const pathData = `M 80 80 L ${x1} ${y1} A 70 70 0 ${largeArcFlag} 1 ${x2} ${y2} Z`;

      return {
        brand, count, percentage: percentage.toFixed(1),
        pathData, color: colors[idx % colors.length]
      };
    });
  }, [stats]);

  if (loading) return <div className={styles.loading}>Загрузка панели управления...</div>;

  const tabsConfig = [
    { key: 'dashboard', label: 'Обзор' },
    { key: 'cars', label: 'Автомобили' },
    { key: 'testdrives', label: 'Тест-драйвы' },
    { key: 'loans', label: 'Кредиты' },
    ...(user?.role === 'admin' ? [{ key: 'users', label: 'Пользователи' }] : [])
  ];

  return (
    <div className={styles.container}>
      <h2 className={styles.title}>Панель управления Luxury Dealer</h2>

      {/* Навигационные табы */}
      <div className={styles.tabs}>
        {tabsConfig.map(tab => (
          <button
            key={tab.key}
            className={`${styles.tab} ${activeTab === tab.key ? styles.active : ''}`}
            onClick={() => setActiveTab(tab.key)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* ВКЛАДКА: ДАШБОРД / ОБЗОР */}
      {activeTab === 'dashboard' && stats && (
        <>
          <div className={styles.dashboard}>
            <div className={styles.statCard}><h3>Всего автомобилей</h3><p>{stats.total_cars}</p></div>
            <div className={styles.statCard}><h3>Пользователей</h3><p>{stats.total_users}</p></div>
            <div className={styles.statCard}><h3>Тест-драйвы</h3><p>{stats.total_test_drives}</p></div>
            <div className={styles.statCard}><h3>Заявки на кредит</h3><p>{stats.total_loans}</p></div>
          </div>

          <div className={styles.analyticsGrid}>
            {/* Секция финансовой выручки */}
            <div className={styles.analyticsBlock}>
              <h3 className={styles.blockTitle}>Общая капитализация автопарка</h3>
              <p className={`${styles.pendingTdCount} ${styles.revenueAmount}`}>
                {stats.total_revenue?.toLocaleString('ru-RU')} ₽
              </p>
              <p className={styles.emptyText} style={{ marginTop: '0.5rem', fontSize: '0.9rem' }}>
                Суммарная стоимость всех доступных автомобилей в салоне
              </p>
            </div>

            {/* Ожидающие тест-драйвы */}
            <div className={styles.analyticsBlock}>
              <h3 className={styles.blockTitle}>Тест‑драйвы (ожидают)</h3>
              <motion.span
                className={styles.pendingTdCount}
                onClick={() => setActiveTab('testdrives')}
                title="Перейти к тест‑драйвам"
                role="button"
                tabIndex={0}
                onKeyDown={(e) => e.key === 'Enter' && setActiveTab('testdrives')}
                animate={{ y: [0, -6, 0] }}
                transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
                whileHover={{ 
                  scale: 1.15,
                  rotate: [0, -3, 3, -3, 0],
                  transition: { duration: 0.3 }
                }}
                whileTap={{ scale: 0.95 }}
              >
                {testDrives.filter(td => td.status === 'pending').length}
              </motion.span>
            </div>

            {/* Распределение марок через Круговую диаграмму */}
            <div className={styles.analyticsBlock}>
              <h3 className={styles.blockTitle}>Доли брендов в автопарке</h3>
              {pieChartData.length === 0 ? (
                <p className={styles.emptyText}>Нет данных для диаграммы</p>
              ) : (
                <div className={styles.pieChartContainer}>
                  <div className={styles.pieChart}>
                    <svg viewBox="0 0 16 16" className={styles.pieSvg}>
                      {pieChartData.map((slice, i) => (
                        <motion.path
                          key={i}
                          d={slice.pathData}
                          fill={slice.color}
                          className={styles.pieSlice}
                          initial={{ opacity: 0, scale: 0.8 }}
                          animate={{ opacity: 1, scale: 1 }}
                          exit={{ opacity: 0, scale: 0.8 }}
                          originX={0.5}
                          originY={0.5}
                          title={`${slice.brand}: ${slice.count} авто (${slice.percentage}%)`}
                        />
                      ))}
                    </svg>
                  </div>
                  <div className={styles.pieLegend}>
                    {pieChartData.slice(0, 5).map((slice, i) => (
                      <div key={i} className={styles.legendItem}>
                        <span className={styles.legendColor} style={{ backgroundColor: slice.color }} />
                        <span className={styles.legendText}>{slice.brand} — {slice.count} ({slice.percentage}%)</span>
                      </div>
                    ))}
                    {pieChartData.length > 5 && (
                      <p className={styles.moreBrands}>и еще {pieChartData.length - 5} брендов...</p>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* Самые дорогие премиум-модели (Объёмные столбцы) */}
            <div className={styles.analyticsBlock}>
              <h3 className={styles.blockTitle}>Топ-3 флагмана по стоимости</h3>
              {cars.length === 0 ? (
                <p className={styles.emptyText}>Автопарк пуст</p>
              ) : (
                <div className={styles.columnChart}>
                  {[...cars].sort((a, b) => b.price - a.price).slice(0, 3).map((car, idx) => {
                    const topCars = [...cars].sort((a, b) => b.price - a.price);
                    const maxPrice = topCars[0]?.price || 1;
                    const heightPercent = (car.price / maxPrice) * 100;
                    const barColors = ['#4a148c', '#7b1fa2', '#9c27b0'];

                    return (
                      <div key={car.id} className={styles.columnItem}>
                        <div className={styles.columnValue}>{(car.price / 1000000).toFixed(1)}M</div>
                        <div className={styles.columnBar}>
                          <div 
                            className={styles.columnFill} 
                            style={{ 
                              height: `${heightPercent}%`, 
                              '--bar-color': barColors[idx]
                            }}
                          >
                            <div className={styles.columnTop} style={{ '--bar-color': barColors[idx] }} />
                          </div>
                        </div>
                        <div className={styles.columnLabel} title={`${car.brand} ${car.model}`}>
                          {car.brand}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </>
      )}

      {/* ВКЛАДКА: ПОЛЬЗОВАТЕЛИ */}
      {activeTab === 'users' && user.role === 'admin' && (
        <table className={styles.table}>
          <thead>
            <tr><th>ID</th><th>Имя</th><th>Email</th><th>Роль</th></tr>
          </thead>
          <tbody>
            {users.map(u => (
              <tr key={u.id}>
                <td>{u.id}</td>
                <td>{u.name}</td>
                <td>{u.email}</td>
                <td>
                  <select
                    value={u.role}
                    disabled={u.id === user.id}
                    className={styles.roleSelect}
                    onChange={(e) => handleRoleChange(u.id, e.target.value)}
                  >
                    {availableRoles.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* ВКЛАДКА: АВТОМОБИЛИ */}
      {activeTab === 'cars' && (
        <div>
          <button className={styles.addBtn} onClick={openAddCarModal}>+ Добавить автомобиль</button>

          {/* Панель расширенных фильтров */}
          <div className={styles.filterPanel}>
            <input type="text" placeholder="Поиск марки или модели..." value={carSearch} onChange={e => setCarSearch(e.target.value)} className={styles.filterInput} />
            <select value={brandFilter} onChange={e => setBrandFilter(e.target.value)} className={styles.filterInput}>
              <option value="">Все марки</option>
              {Object.keys(brandModels).map(b => <option key={b} value={b}>{b}</option>)}
            </select>
            <select value={bodyTypeFilter} onChange={e => setBodyTypeFilter(e.target.value)} className={styles.filterInput}>
              <option value="">Все кузова</option>
              {Object.entries(bodyTypesRussian).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
            </select>
            <input type="number" placeholder="Цена от" value={priceMin} onChange={e => setPriceMin(e.target.value)} className={styles.filterInputSmall} />
            <input type="number" placeholder="Цена до" value={priceMax} onChange={e => setPriceMax(e.target.value)} className={styles.filterInputSmall} />
            <button onClick={resetFilters} className={styles.resetFiltersBtn}>Сбросить</button>
          </div>

          <table className={styles.table}>
            <thead>
              <tr>
                <th onClick={() => handleSort('id')} className={styles.sortable}>ID {sortField === 'id' && (sortOrder === 'asc' ? '▲' : '▼')}</th>
                <th onClick={() => handleSort('brand')} className={styles.sortable}>Марка {sortField === 'brand' && (sortOrder === 'asc' ? '▲' : '▼')}</th>
                <th onClick={() => handleSort('model')} className={styles.sortable}>Модель {sortField === 'model' && (sortOrder === 'asc' ? '▲' : '▼')}</th>
                <th onClick={() => handleSort('year')} className={styles.sortable}>Год {sortField === 'year' && (sortOrder === 'asc' ? '▲' : '▼')}</th>
                <th onClick={() => handleSort('price')} className={styles.sortable}>Цена {sortField === 'price' && (sortOrder === 'asc' ? '▲' : '▼')}</th>
                <th>Кузов</th>
                <th>Статус</th>
                <th>Действия</th>
              </tr>
            </thead>
            <tbody>
              {processedCars.map(car => (
                <tr key={car.id}>
                  <td>{car.id}</td>
                  <td>{car.brand}</td>
                  <td>{car.model}</td>
                  <td>{car.year}</td>
                  <td>{car.price?.toLocaleString()} ₽</td>
                  <td>{bodyTypesRussian[car.body_type] || car.body_type}</td>
                  <td>
                    <span className={`${styles.status} ${car.is_available !== false ? styles.approved : styles.rejected}`}>
                      {car.is_available !== false ? 'В наличии' : 'Продан'}
                    </span>
                  </td>
                  <td className={styles.actionsCell}>
                    <button className={styles.editBtn} onClick={() => openEditCarModal(car)}>Редактировать</button>
                    <button className={`${styles.editBtn} ${styles.deleteCarBtn}`} onClick={() => handleDeleteCar(car.id)}>Удалить</button>
                  </td>
                </tr>
              ))}
              {processedCars.length === 0 && (
                <tr><td colSpan="8" style={{ textAlign: 'center', padding: '2rem' }}>Ничего не найдено по выбранным фильтрам</td></tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* ВКЛАДКА: ТЕСТ-ДРАЙВЫ */}
      {activeTab === 'testdrives' && (
        <table className={styles.table}>
          <thead>
            <tr><th>ID</th><th>Пользователь</th><th>Автомобиль</th><th>Дата и Время</th><th>Статус</th><th>Действия</th></tr>
          </thead>
          <tbody>
            {testDrives.map(td => (
              <tr key={td.id}>
                <td>{td.id}</td>
                <td>{td.user_email || `ID: ${td.user_id}`}</td>
                <td>{td.car_brand} {td.car_model} (ID: {td.car_id})</td>
                <td>{new Date(td.date).toLocaleDateString()} в {td.time}</td>
                <td>
                  <span className={`${styles.status} ${styles[td.status]}`}>
                    {td.status === 'pending' ? 'Ожидает' : td.status === 'approved' ? 'Одобрен' : 'Отклонен'}
                  </span>
                </td>
                <td className={styles.actionsCell}>
                  {td.status === 'pending' && (
                    <>
                      <button className={styles.approveBtn} onClick={() => handleTestDriveStatus(td.id, 'approved')}>Одобрить</button>
                      <button className={styles.rejectBtn} onClick={() => handleTestDriveStatus(td.id, 'rejected')}>Отклонить</button>
                    </>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* ВКЛАДКА: КРЕДИТЫ */}
      {activeTab === 'loans' && (
        <table className={styles.table}>
          <thead>
            <tr><th>ID</th><th>Пользователь</th><th>Автомобиль</th><th>Параметры кредита</th><th>Статус</th><th>Комментарий салона</th><th>Действия</th></tr>
          </thead>
          <tbody>
            {loans.map(l => (
              <tr key={l.id}>
                <td>{l.id}</td>
                <td>{l.user_email || `ID: ${l.user_id}`}</td>
                <td>{l.car_brand} {l.car_model}</td>
                <td>
                  <div>Сумма: {l.amount?.toLocaleString()} ₽</div>
                  <div>Срок: {l.term_months} мес.</div>
                  <div>Ставка: {l.interest_rate}%</div>
                </td>
                <td>
                  <span className={`${styles.status} ${styles[l.status]}`}>
                    {l.status === 'pending' ? 'На рассмотрении' : l.status === 'approved' ? 'Выдан' : 'Отказ'}
                  </span>
                </td>
                <td style={{ maxWidth: '200px', wordBreak: 'break-word', fontSize: '0.9rem', fontStyle: 'italic' }}>
                  {l.comment || <span style={{ opacity: 0.4 }}>—</span>}
                </td>
                <td className={styles.actionsCell}>
                  {l.status === 'pending' && (
                    <>
                      <button className={styles.approveBtn} onClick={() => handleLoanStatus(l.id, 'approved')}>Одобрить кредит</button>
                      <button className={styles.rejectBtn} onClick={() => openRejectCommentModal(l.id)}>Отказать</button>
                    </>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* МОДАЛЬНОЕ ОКНО: ОТКАЗ ПО КРЕДИТУ */}
      <AnimatePresence>
        {showCommentModal && (
          <motion.div className={styles.modelOverlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            <motion.div className={styles.loanCommentModal} initial={{ scale: 0.9 }} animate={{ scale: 1 }} exit={{ scale: 0.9 }}>
              <h4>Укажите причину отказа</h4>
              <textarea
                className={styles.loanCommentTextarea}
                rows="4"
                placeholder="Причина отказа (будет видна клиенту в личном кабинете)..."
                value={rejectComment}
                onChange={e => setRejectComment(e.target.value)}
              />
              <div className={styles.loanCommentButtons}>
                <button className={styles.cancelBtn} onClick={() => setShowCommentModal(false)}>Отмена</button>
                <button className={styles.submitBtn} style={{ padding: '0.5rem 1.5rem' }} onClick={submitLoanReject}>Подтвердить отказ</button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* МОДАЛЬНОЕ ОКНО: ФОРМА АВТОМОБИЛЯ */}
      <AnimatePresence>
        {showCarModal && (
          <motion.div className={styles.modalOverlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowCarModal(false)}>
            <motion.div className={styles.modal} initial={{ y: 50, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 50, opacity: 0 }} onClick={e => e.stopPropagation()}>
              
              <div className={styles.modalHeader}>
                <h4>{editingCarId ? `Редактирование авто (ID: ${editingCarId})` : 'Добавление нового автомобиля'}</h4>
                <button type="button" onClick={() => setShowCarModal(false)} className={styles.closeBtn}>✕</button>
              </div>

              <div className={styles.modalBody}>
                <form id="carAdminForm" onSubmit={handleCarFormSubmit}>
                  
                  {/* Строка 1: Марка и Модель через Модалки выбора */}
                  <div className={styles.formRow}>
                    <div className={styles.formGroup}>
                      <label>Марка *</label>
                      <div className={`${styles.selectField} ${!carForm.brand ? styles.placeholder : ''}`} onClick={() => setShowBrandModal(true)}>
                        {carForm.brand || 'Выберите марку...'}
                      </div>
                      {formErrors.brand && <span className={styles.errorMsg}>{formErrors.brand}</span>}
                    </div>

                    <div className={styles.formGroup}>
                      <label>Модель *</label>
                      <div className={`${styles.selectField} ${!carForm.model ? styles.placeholder : ''} ${!carForm.brand ? styles.disabled : ''}`} onClick={() => carForm.brand && setShowModelModal(true)}>
                        {carForm.model || (carForm.brand ? 'Выберите модель...' : 'Сначала выберите марку')}
                      </div>
                      {formErrors.model && <span className={styles.errorMsg}>{formErrors.model}</span>}
                    </div>
                  </div>

                  {/* Строка 2: Год и Цена */}
                  <div className={styles.formRow}>
                    <div className={styles.formGroup}>
                      <label htmlFor="formYear">Год выпуска *</label>
                      <input id="formYear" type="number" className={formErrors.year ? styles.inputError : ''} value={carForm.year} onChange={e => setCarForm({ ...carForm, year: e.target.value })} />
                      {formErrors.year && <span className={styles.errorMsg}>{formErrors.year}</span>}
                    </div>
                    <div className={styles.formGroup}>
                      <label htmlFor="formPrice">Цена (₽) *</label>
                      <input id="formPrice" type="number" className={formErrors.price ? styles.inputError : ''} value={carForm.price} onChange={e => setCarForm({ ...carForm, price: e.target.value })} placeholder="Например: 12500000" />
                      {formErrors.price && <span className={styles.errorMsg}>{formErrors.price}</span>}
                    </div>
                  </div>

                  {/* Строка 3: Кузов и Наличие */}
                  <div className={styles.formRow}>
                    <div className={styles.formGroup}>
                      <label htmlFor="formBodyType">Тип кузова</label>
                      <select id="formBodyType" value={carForm.body_type} onChange={e => handleBodyTypeChangeInForm(e.target.value)}>
                        {Object.entries(bodyTypesRussian).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
                      </select>
                    </div>
                    <div className={styles.formGroup}>
                      <label>Статус наличия</label>
                      <div className={styles.checkboxLabel}>
                        <div className={`${styles.toggleSwitch} ${carForm.is_available ? styles.toggleActive : ''}`} onClick={() => setCarForm({ ...carForm, is_available: !carForm.is_available })}>
                          <div className={styles.toggleKnob} />
                        </div>
                        <span>{carForm.is_available ? 'В наличии на складе' : 'Продан / Снят с продажи'}</span>
                      </div>
                    </div>
                  </div>

                  {/* Технические характеристики автомобиля */}
                  <fieldset className={styles.imagePanel} style={{ border: 'none', padding: '1rem', marginTop: '1rem' }}>
                    <legend style={{ fontWeight: 600, color: 'var(--primary)', marginBottom: '0.5rem' }}>Технические характеристики (Генерируются автоподбором)</legend>
                    <div className={styles.specsGrid}>
                      <div className={styles.formGroup}>
                        <label htmlFor="specVol">Объем двигателя (л)</label>
                        <select id="specVol" value={carForm.engine_volume} onChange={e => setCarForm({ ...carForm, engine_volume: e.target.value })}>
                          {engineVolumes.map(v => <option key={v} value={v}>{v.toFixed(1)} л</option>)}
                        </select>
                      </div>
                      <div className={styles.formGroup}>
                        <label htmlFor="specPow">Мощность (л.с.)</label>
                        <select id="specPow" value={carForm.power} onChange={e => setCarForm({ ...carForm, power: e.target.value })}>
                          {powerValues.map(p => <option key={p} value={p}>{p} л.с.</option>)}
                        </select>
                      </div>
                      <div className={styles.formGroup}>
                        <label htmlFor="specFuel">Тип топлива</label>
                        <select id="specFuel" value={carForm.fuel_type} onChange={e => setCarForm({ ...carForm, fuel_type: e.target.value })}>
                          <option value="petrol">Бензин</option><option value="diesel">Дизель</option>
                          <option value="hybrid">Гибрид</option><option value="electric">Электро</option>
                        </select>
                      </div>
                      <div className={styles.formGroup}>
                        <label htmlFor="specDrive">Привод</label>
                        <select id="specDrive" value={carForm.drive_type} onChange={e => setCarForm({ ...carForm, drive_type: e.target.value })}>
                          <option value="AWD">Полный (AWD)</option><option value="RWD">Задний (RWD)</option><option value="FWD">Передний (FWD)</option>
                        </select>
                      </div>
                      <div className={styles.formGroup}>
                        <label htmlFor="specTrans">КПП</label>
                        <select id="specTrans" value={carForm.transmission} onChange={e => setCarForm({ ...carForm, transmission: e.target.value })}>
                          <option value="automatic">Автомат</option><option value="manual">Механика</option><option value="robot">Робот</option>
                        </select>
                      </div>
                      <div className={styles.formGroup}>
                        <label htmlFor="specSeats">Мест</label>
                        <select id="specSeats" value={carForm.seats} onChange={e => setCarForm({ ...carForm, seats: e.target.value })}>
                          {seatValues.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                      </div>
                      <div className={styles.formGroup}>
                        <label htmlFor="specAcc">Разгон 0-100 (с)</label>
                        <input id="specAcc" type="number" step="0.1" value={carForm.acceleration} onChange={e => setCarForm({ ...carForm, acceleration: e.target.value })} />
                      </div>
                      <div className={styles.formGroup}>
                        <label htmlFor="specSpeed">Макс. скорость (км/ч)</label>
                        <input id="specSpeed" type="number" value={carForm.max_speed} onChange={e => setCarForm({ ...carForm, max_speed: e.target.value })} />
                      </div>
                      <div className={styles.formGroup}>
                        <label htmlFor="specCons">Расход (л/100км)</label>
                        <input id="specCons" type="number" step="0.1" value={carForm.consumption} onChange={e => setCarForm({ ...carForm, consumption: e.target.value })} />
                      </div>
                      <div className={styles.formGroup}>
                        <label htmlFor="specClear">Клиренс (мм)</label>
                        <input id="specClear" type="number" value={carForm.clearance} onChange={e => setCarForm({ ...carForm, clearance: e.target.value })} />
                      </div>
                    </div>
                  </fieldset>

                  {/* Описание */}
                  <div className={styles.formGroup} style={{ marginTop: '1rem' }}>
                    <label htmlFor="formDesc">Описание комплектации и автомобиля</label>
                    <textarea id="formDesc" rows="4" value={carForm.description} onChange={e => setCarForm({ ...carForm, description: e.target.value })} placeholder="Опишите эксклюзивные опции, цвет кузова, состояние салона..." />
                  </div>

                  {/* Работа с изображениями */}
                  <div className={styles.imagePanel}>
                    <label style={{ fontWeight: 600, display: 'block', marginBottom: '0.5rem' }}>Фотогалерея автомобиля</label>
                    <div className={styles.uploadArea} onClick={() => fileInputRef.current.click()}>
                      <div className={styles.uploadIcon}>📁</div>
                      <div className={styles.uploadTitle}>Перетащите фотографии или кликните для загрузки</div>
                      <div className={styles.uploadSubtitle}>Поддерживаются форматы PNG, JPG, JPEG</div>
                      <input type="file" ref={fileInputRef} multiple accept="image/*" style={{ display: 'none' }} onChange={handleFileChange} />
                    </div>

                    {selectedFiles.length > 0 && (
                      <div style={{ marginTop: '0.5rem', fontSize: '0.9rem', color: 'var(--primary)' }}>
                        Выбрано новых файлов для загрузки: <strong>{selectedFiles.length} шт.</strong>
                      </div>
                    )}

                    {/* Отображение уже существующих фото автомобиля в БД */}
                    {editingCarId && cars.find(c => c.id === editingCarId)?.images?.length > 0 && (
                      <div style={{ marginTop: '1rem' }}>
                        <p style={{ fontSize: '0.85rem', fontWeight: 600, opacity: 0.7, marginBottom: '0.4rem' }}>Сохраненные фото (кликните на крестик для удаления):</p>
                        <div className={styles.imageGrid}>
                          {cars.find(c => c.id === editingCarId).images.map((img, index) => {
                            const path = img.image_path || img;
                            return (
                              <div key={index} className={styles.thumbnailContainer}>
                                <img src={getImageUrl(path)} alt="Миниатюра" />
                                <button type="button" className={styles.deleteThumb} onClick={() => handleDeleteExistingImage(editingCarId, path)}>✕</button>
                                {index === 0 && <span className={styles.mainPhotoBadge}>Главное</span>}
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    )}
                  </div>

                  {serverError && <div className={styles.serverError}>{serverError}</div>}
                </form>
              </div>

              <div className={styles.modalFooter}>
                <button type="button" className={styles.cancelBtn} style={{ marginRight: '1rem' }} onClick={() => setShowCarModal(false)}>Отмена</button>
                <button type="submit" form="carAdminForm" className={styles.submitBtn} disabled={uploadingImages}>
                  {uploadingImages ? 'Загрузка медиа файлов...' : editingCarId ? 'Сохранить изменения' : 'Создать карточку авто'}
                </button>
              </div>

            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* УМНАЯ МОДАЛКА: ВЫБОР МАРКИ */}
      <AnimatePresence>
        {showBrandModal && (
          <motion.div className={styles.modelOverlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowBrandModal(false)}>
            <motion.div className={styles.modelModal} initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }} onClick={e => e.stopPropagation()}>
              <div className={styles.modelModalHeader}><h4>Выберите марку</h4><button type="button" onClick={() => setShowBrandModal(false)} className={styles.closeBtn}>✕</button></div>
              <input type="text" placeholder="Поиск марки..." value={brandSearch} onChange={e => setBrandSearch(e.target.value)} className={styles.modelSearchInput} autoFocus />
              <div className={styles.modelList}>
                {filteredBrandKeys.map(brand => (
                  <button key={brand} type="button" className={`${styles.modelItem} ${brand === carForm.brand ? styles.modelItemActive : ''}`} onClick={() => selectBrand(brand)}>
                    {brand}
                  </button>
                ))}
                {filteredBrandKeys.length === 0 && <p className={styles.noModels}>Нет подходящих марок</p>}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* УМНАЯ МОДАЛКА: ВЫБОР МОДЕЛИ */}
      <AnimatePresence>
        {showModelModal && (
          <motion.div className={styles.modelOverlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowModelModal(false)}>
            <motion.div className={styles.modelModal} initial={{ scale: 0.9, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }} onClick={e => e.stopPropagation()}>
              <div className={styles.modelModalHeader}><h4>Выберите модель</h4><button type="button" onClick={() => setShowModelModal(false)} className={styles.closeBtn}>✕</button></div>
              <input type="text" placeholder="Поиск модели..." value={modelSearch} onChange={e => setModelSearch(e.target.value)} className={styles.modelSearchInput} autoFocus />
              <div className={styles.modelList}>
                {filteredModels.map(model => (
                  <button key={model} type="button" className={`${styles.modelItem} ${model === carForm.model ? styles.modelItemActive : ''}`} onClick={() => selectModel(model)}>
                    {model}
                  </button>
                ))}
                {filteredModels.length === 0 && <p className={styles.noModels}>Нет подходящих моделей</p>}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AdminPanel;
